(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB1LA_1LA1RC_1RB1RD_1RB0LA : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S0;S1;S1] [] 0 0 [])) (mkC StC (mkS [S1;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S0;S1;S1] [] 0 0 [])) (mkC StC (mkS [S1;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)])].
Local Notation lad := lad_0RB1LA_1LA1RC_1RB1RD_1RB0LA.

Definition rules_0RB1LA_1LA1RC_1RB1RD_1RB0LA : list LRule := map fst lad.
Local Notation rules := rules_0RB1LA_1LA1RC_1RB1RD_1RB0LA.

Lemma ladder_ok_0RB1LA_1LA1RC_1RB1RD_1RB0LA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB1LA_1LA1RC_1RB1RD_1RB0LA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB1LA_1LA1RC_1RB1RD_1RB0LA. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(* A[0] L<> R<110^1+y0>  ==>  A[0] L<> R<1^4+3*y0>   [8+6*y0 steps] *)
Definition arm13_0RB1LA_1LA1RC_1RB1RD_1RB0LA : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S0;S1;S1;S0;S1;S1;S0] [S1;S1;S0] 1 0 []))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1;S1;S1;S1;S1;S1;S1] [S1;S1;S1] 1 0 [S1])) 6 20.
Definition ch_arm13_0RB1LA_1LA1RC_1RB1RD_1RB0LA : list rstep := [RB (SWin 9);RB (SCycR 3);RB (SWinR 2);RB (SCycL 3 0);RB (SWin 9)].
Lemma ok_arm13_0RB1LA_1LA1RC_1RB1RD_1RB0LA :
  check_arm tm true true rules arm13_0RB1LA_1LA1RC_1RB1RD_1RB0LA ch_arm13_0RB1LA_1LA1RC_1RB1RD_1RB0LA = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm13_0RB1LA_1LA1RC_1RB1RD_1RB0LA : RuleSound tm true true arm13_0RB1LA_1LA1RC_1RB1RD_1RB0LA.
Proof. eapply arm_sound; [exact rules_sound_0RB1LA_1LA1RC_1RB1RD_1RB0LA | exact ok_arm13_0RB1LA_1LA1RC_1RB1RD_1RB0LA]. Qed.

