Lemma farm_sound_0RB1LA_1LA1RC_1RD0LB_1RB0LA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_0RB1LA_1LA1RC_1RD0LB_1RB0LA r ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  {
    destruct ph as [|ph].
    { eapply arm_sound; [exact rules_sound_0RB1LA_1LA1RC_1RD0LB_1RB0LA | exact ok_farm1_0_0RB1LA_1LA1RC_1RD0LB_1RB0LA]. }
    exfalso; lia.
