  match r, ph with
  | 1, 0 => farm1_0_0RB1LA_1LC1RD_1RA1RC_1RB0LA
  | _, _ => farm1_0_0RB1LA_1LC1RD_1RA1RC_1RB0LA  (* unreachable: 0 < r < N0 + st *)
  end.

