(** ** What this board establishes

    21 of 22 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 22 of them
    collapse to 3 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [] [S1;S0;S0] 1 0 [S1;S1;S1]))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1])) 6 4.
Definition ch_iarm0_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA : list rstep := [RB (SRotR 1);RB (SWin 1);RB (SCycR 3);RB (SWin 2);RB (SCycL 3 0);RB (SWin 1);RB (SUnrotR 1)].
Lemma ok_iarm0_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA :
  check_arm tm true false rules iarm0_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA
            ch_iarm0_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm1_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [] [S1;S0;S0] 1 0 [S1;S0;S1]))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [] [S1;S1;S1] 1 0 [S1;S0;S0])) 6 6.
Definition ch_iarm1_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA : list rstep := [RB (SRotR 1);RB (SWin 1);RB (SCycR 3);RB (SWin 4);RB (SCycL 3 0);RB (SWin 1);RB (SUnrotR 1)].
Lemma ok_iarm1_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA :
  check_arm tm true false rules iarm1_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA
            ch_iarm1_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_0RB1LA_1LC1RD_1RB0LD_1RC0LA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA
  | 1, 0 => iarm1_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA
  | _, _ => iarm0_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0;S0] [S1;S0;S0] 1 0 []))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [] [S1;S1;S1] 1 0 [S1;S0;S0;S1])) 6 8.
Definition ch_farm1_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWinR 2);RB (SRotL 1);RB (SWin 1);RB (SRotL 1);RB (SWin 1);RB (SCycL 3 0);RB (SWin 1);RB (SUnrotR 1)].
Lemma ok_farm1_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA :
  check_arm tm true true rules farm1_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA
            ch_farm1_0_0RB1LA_1LC1RD_1RB0LD_1RC0LA = true.
Proof. vm_compute. reflexivity. Qed.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
