Lemma farm_cb_0RB1LA_1RC0LA_1LA1RD_1RB0LC : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 -> 0 < lr_cb (farm_0RB1LA_1RC0LA_1LA1RD_1RB0LC r ph).
Proof.
